import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import { TenantScopeError } from "@/lib/tenant";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let north: Tenant;
let acme: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  north = await createTenant("north-scratch");
  acme = await createTenant("acme-scratch");
});

afterAll(() => {
  cleanup();
});

async function newIssue(author: Tenant, overrides: { assigneeId?: string | null; title: string }) {
  return issueService.createIssue(
    author.actors.member,
    issueInput(author.org.id, author.project.id, {
      title: overrides.title,
      assigneeId: (overrides.assigneeId ?? null) as never,
    }),
  );
}

async function comment(tenant: Tenant, issue: Issue, userId: string, parentId: string | null = null) {
  return commentRepo.insertComment(
    {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "x",
      parentId: parentId as never,
      mentionedUserIds: [],
    },
    userId as never,
  );
}

describe("getIssueParticipants (scratch)", () => {
  it("unions author, assignee and live comment authors, deduped, excluding deleted-only", async () => {
    const issue = await newIssue(north, {
      title: "Participants A",
      assigneeId: north.userIds.admin,
    });

    // member is author AND commenter -> appears once
    await comment(north, issue, north.userIds.member);
    // viewer comments live -> included
    const viewerComment = await comment(north, issue, north.userIds.viewer);
    // owner replies to viewer (replies count) -> included
    await comment(north, issue, north.userIds.owner, viewerComment.id);
    // owner's only other comment is deleted; owner is already included via reply,
    // so use a separate issue to test deleted-only below
    const issue2 = await newIssue(north, { title: "Participants B" });
    const deletedOnly = await comment(north, issue2, north.userIds.owner);
    await commentRepo.archiveComment(north.org.id, deletedOnly.id);

    const got = await commentService.getIssueParticipants(
      north.actors.viewer,
      north.org.id,
      issue.id,
    );
    expect([...got].sort()).toEqual(
      [north.userIds.member, north.userIds.admin, north.userIds.viewer, north.userIds.owner].sort(),
    );
    expect(new Set(got).size).toBe(got.length);

    const got2 = await commentService.getIssueParticipants(
      north.actors.viewer,
      north.org.id,
      issue2.id,
    );
    expect(got2).toEqual([north.userIds.member]);
  });

  it("excludes removed members, including the issue author and commenters", async () => {
    const issue = await newIssue(acme, { title: "Removal" , assigneeId: acme.userIds.admin });
    await comment(acme, issue, acme.userIds.viewer);

    // Remove the viewer (commenter) and the admin (assignee) from acme.
    const viewerMember = await memberRepo.findMember(acme.org.id, acme.userIds.viewer);
    await memberRepo.archiveMember(acme.org.id, viewerMember!.id);
    const adminMember = await memberRepo.findMember(acme.org.id, acme.userIds.admin);
    await memberRepo.archiveMember(acme.org.id, adminMember!.id);

    const got = await commentService.getIssueParticipants(
      acme.actors.owner,
      acme.org.id,
      issue.id,
    );
    expect(got).toEqual([acme.userIds.member]);

    // Removed author: author is the member, remove them -> excluded.
    const memberMember = await memberRepo.findMember(acme.org.id, acme.userIds.member);
    await memberRepo.archiveMember(acme.org.id, memberMember!.id);
    const got2 = await commentService.getIssueParticipants(
      acme.actors.owner,
      acme.org.id,
      issue.id,
    );
    expect(got2).toEqual([]);
  });

  it("rejects another organization's orgId with TenantScopeError", async () => {
    const issue = await newIssue(north, { title: "Tenant check" });
    await expect(
      commentService.getIssueParticipants(north.actors.member, acme.org.id, issue.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("returns NotFound for an issue id that belongs to another organization", async () => {
    const issue = await newIssue(north, { title: "Cross org id" });
    await expect(
      commentService.getIssueParticipants(acme.actors.owner, acme.org.id, issue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("lets viewers read participants", async () => {
    const issue = await newIssue(north, { title: "Viewer read" });
    await expect(
      commentService.getIssueParticipants(north.actors.viewer, north.org.id, issue.id),
    ).resolves.toEqual([north.userIds.member]);
  });

  it("repository returns distinct live author ids in the org only", async () => {
    const issue = await newIssue(north, { title: "Repo distinct" });
    await comment(north, issue, north.userIds.owner);
    await comment(north, issue, north.userIds.owner);
    const del = await comment(north, issue, north.userIds.admin);
    await commentRepo.archiveComment(north.org.id, del.id);

    const ids = await commentRepo.listCommentAuthorIds(north.org.id, issue.id);
    expect(ids).toEqual([north.userIds.owner]);

    await expect(
      commentRepo.listCommentAuthorIds(acme.org.id, issue.id),
    ).resolves.toEqual([]);
    void issueRepo;
  });
});

